package com.hospital.system; import com.hospital.system.dto.AppointmentRequest; import com.hospital.system.repository.*; import com.hospital.system.service.AppointmentService; import org.junit.jupiter.api.Test; import org.mockito.Mockito; import java.time.*; import static org.junit.jupiter.api.Assertions.*; class AppointmentServiceTest { @Test void duplicateSlotRejected(){AppointmentRepository ar=Mockito.mock(AppointmentRepository.class); PatientRepository pr=Mockito.mock(PatientRepository.class); DoctorRepository dr=Mockito.mock(DoctorRepository.class); Mockito.when(pr.one(1L)).thenReturn(java.util.Optional.of(new com.hospital.system.model.Patient())); Mockito.when(dr.one(1L)).thenReturn(java.util.Optional.of(new com.hospital.system.model.Doctor())); Mockito.when(ar.existsSlot(1L,LocalDate.of(2026,10,1),LocalTime.of(10,0))).thenReturn(true); AppointmentService s=new AppointmentService(ar,pr,dr); AppointmentRequest x=new AppointmentRequest();x.patientId=1L;x.doctorId=1L;x.appointmentDate=LocalDate.of(2026,10,1);x.appointmentTime=LocalTime.of(10,0);assertThrows(RuntimeException.class,()->s.add(x));} }
